import bt,numpy as np
s=bt.signals();R=bt.train_returns().astype(float)
sh=R.mean(0)/R.std(0)*np.sqrt(252); vol=R.std(0)
C={}
fam=lambda f:[i for i,n in enumerate(s) if n.startswith(f)]
for f in ['hold_','tsmom_','ma_']:
    C['eq_'+f]={s[i]:1/vol[i] for i in fam(f)}
for L in [5,21,63,126,252]:
    C[f'tsmom{L}']={s[i]:1/vol[i] for i,n in enumerate(s) if n.startswith('tsmom') and n.endswith(f'_{L}')}
for p in ['5_21','21_63','50_200']:
    C['ma'+p]={s[i]:1/vol[i] for i,n in enumerate(s) if n.startswith('ma') and n.endswith('_'+p)}
C['trend_all']={s[i]:1/vol[i] for i,n in enumerate(s) if not n.startswith('hold')}
for k in [10,25,50,100]:
    o=np.argsort(-sh)[:k]; C[f'top{k}']={s[i]:1/vol[i] for i in o}
C['signsh']={s[i]:np.sign(sh[i])/vol[i] for i in range(len(s))}
C['shw']={s[i]:sh[i]/vol[i] for i in range(len(s))}
# shrunk MV
Sig=np.cov(R.T); d=np.diag(np.diag(Sig))
for a in [0.5,0.9]:
    w=np.linalg.solve(a*d+(1-a)*Sig,R.mean(0)); C[f'mv{a}']={s[i]:float(w[i]) for i in range(len(s))}
res={}
for k,w in C.items():
    w={a:float(b) for a,b in w.items()}
    r=bt.backtest(w);res[k]=r;print(k,r)
EOF
